    99	async function atomicWrite(filePath: string, content: string): Promise<void> {
   100	  await mkdir(path.dirname(filePath), { recursive: true });
   101	  const temporaryPath = path.join(path.dirname(filePath), `.${path.basename(filePath)}.${randomUUID()}.tmp`);
   102	  try {
   103	    await writeFile(temporaryPath, content, { encoding: "utf8", mode: 0o600 });
   104	    await rename(temporaryPath, filePath);
   105	  } catch (error) {
   106	    await rm(temporaryPath, { force: true });
   107	    throw error;
   108	  }
