   111	async function loadTemplates(assetsDir: string): Promise<readonly Template[]> {
   112	  return await Promise.all(
   113	    PROFILE_NAMES.map(async (name) => {
   114	      const assetPath = path.join(assetsDir, `${name}.toml`);
   115	      const content = await readFile(assetPath, "utf8");
   116	      const parsed: unknown = Bun.TOML.parse(content);
   117	      if (!isRecord(parsed)) throw new Error(`${assetPath} must contain a TOML table.`);
   118	      for (const key of ["model", "model_reasoning_effort", "developer_instructions", "sandbox_mode"] as const) {
   119	        if (typeof parsed[key] !== "string" || parsed[key].length === 0) {
   120	          throw new Error(`${assetPath} must define a non-empty ${key}.`);
   121	        }
   122	      }
   123	      return { name, content, checksum: checksum(content) };
   124	    }),
   125	  );
   126	}
