   128	async function readLedger(ledgerPath: string): Promise<Ledger> {
   129	  const content = await readOptional(ledgerPath);
   130	  if (content === null) return { version: LEDGER_VERSION, profiles: {} };
   131	
   132	  const parsed: unknown = JSON.parse(content);
   133	  if (!isRecord(parsed) || parsed.version !== LEDGER_VERSION || !isRecord(parsed.profiles)) {
   134	    throw new Error(`Invalid Agent Kit profile ledger: ${ledgerPath}`);
   135	  }
   136	
   137	  const profiles: Partial<Record<ProfileName, LedgerProfile>> = {};
   138	  for (const name of PROFILE_NAMES) {
   139	    const entry = parsed.profiles[name];
   140	    if (entry === undefined) continue;
   141	    if (!isRecord(entry) || typeof entry.checksum !== "string") {
   142	      throw new Error(`Invalid ${name} entry in Agent Kit profile ledger: ${ledgerPath}`);
   143	    }
   144	    profiles[name] = { checksum: entry.checksum };
   145	  }
   146	  return { version: LEDGER_VERSION, profiles };
   147	}
