   152	
   153	export async function planProfiles(options: InstallOptions): Promise<readonly ProfileAction[]> {
   154	  const paths = resolvePaths(options);
   155	  const [templates, ledger] = await Promise.all([loadTemplates(paths.assetsDir), readLedger(paths.ledgerPath)]);
   156	
   157	  return await Promise.all(
   158	    templates.map(async (template): Promise<ProfileAction> => {
   159	      const targetPath = path.join(paths.agentsDir, `${template.name}.toml`);
   160	      const installed = await readOptional(targetPath);
   161	      if (installed === null) {
   162	        return { name: template.name, targetPath, kind: "create", detail: "profile is not installed" };
   163	      }
   164	
   165	      const installedChecksum = checksum(installed);
   166	      if (installedChecksum === template.checksum) {
   167	        return { name: template.name, targetPath, kind: "unchanged", detail: "profile matches the plugin" };
   168	      }
   169	
   170	      if (installedChecksum === ledger.profiles[template.name]?.checksum) {
   171	        return { name: template.name, targetPath, kind: "update", detail: "previously managed profile has an update" };
   172	      }
   173	
   174	      return {
   175	        name: template.name,
   176	        targetPath,
   177	        kind: "conflict",
   178	        detail: "profile is unmanaged or was modified locally",
   179	      };
   180	    }),
   181	  );
   182	}
