   184	export async function applyProfiles(options: InstallOptions): Promise<readonly ProfileAction[]> {
   185	  const paths = resolvePaths(options);
   186	  const [actions, templates] = await Promise.all([planProfiles(options), loadTemplates(paths.assetsDir)]);
   187	  const conflicts = actions.filter((action) => action.kind === "conflict");
   188	  if (conflicts.length > 0) {
   189	    throw new Error(`Refusing to overwrite conflicting profiles: ${conflicts.map((action) => action.name).join(", ")}`);
   190	  }
